-- Options.lua
L["While you're flagged for PvP (not in dungeons or raids, nor on flights), and in battlegrounds and arenas."] = "Mientras tienes el JcJ activado (no en mazmorras ni bandas, ni en vuelos), y en campos de batalla y arenas."
