L["Previewing: %s (%02d:00)"] = "Vista previa: %s (%02d:00)"
L["Now: %s (%02d:%02d your time)"] = "Ahora: %s (%02d:%02d, tu hora)"
L["Now: %s (%02d:%02d game time)"] = "Ahora: %s (%02d:%02d, hora del juego)"
L["Custom color"] = "Color personalizado"
L["Click to choose the color used by the Custom preset."] = "Haz clic para elegir el color que usa el preajuste Personalizado."
L["Subtle drift"] = "Variación sutil"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive. Paused while the Style tab is open."] = "La intensidad del tinte sube y baja lentamente a lo largo de unos minutos, para que una escena quieta parezca un poco más viva. En pausa mientras la pestaña Estilo está abierta."
L["How strong"] = "Intensidad"
L["How strongly the tint colors the world, for every preset."] = "Cuánto tiñe el mundo el tinte, con cualquier preajuste."
L["Classic boost"] = "Refuerzo Classic"
L["Makes the tint stronger on this client, whose brighter, more colorful world shows the same tint less than retail does. Off: the tint as the Strength slider sets it."] = "Hace el tinte más fuerte en este cliente, cuyo mundo más claro y colorido muestra el mismo tinte menos que retail. Desactivado: el tinte tal como lo pone el control de Intensidad."
L["Drift amount"] = "Cantidad de variación"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive: how far either way, as a share of the strength. Paused while the Style tab is open. Off: it stays put."] = "La intensidad del tinte sube y baja lentamente a lo largo de unos minutos, para que una escena quieta parezca un poco más viva: cuánto hacia cada lado, como parte de la intensidad. En pausa mientras la pestaña Estilo está abierta. Desactivado: se queda fija."
L["Time of day"] = "Hora del día"
L["For the Time of day and Zone + time of day presets, and the time of day message."] = "Para los preajustes Hora del día y Zona + hora del día, y el mensaje de la hora del día."
L["Follows"] = "Sigue"
L["Game time (matches the game's day and night)"] = "Hora del juego (coincide con el día y la noche del juego)"
L["Your computer's clock"] = "El reloj de tu ordenador"
L["Time of day strength"] = "Intensidad de la hora del día"
L["How strongly the time-of-day color applies, in Time of day and Zone + time of day. Lower it for softer nights; 0 leaves just the zone mood."] = "Con qué fuerza se aplica el color de la hora del día, en Hora del día y Zona + hora del día. Bájala para noches más suaves; 0 deja solo el ambiente de la zona."
L["Phases (click a color to change it)"] = "Fases (haz clic en un color para cambiarlo)"
L["Reset"] = "Restablecer"
L["Back to the built-in color and strength."] = "Vuelve al color y la intensidad integrados."
L["Choose your own color for %s."] = "Elige tu propio color para %s."
L["Zone tints"] = "Tintes de zona"
L["Give the zone you're standing in, or just the area within it (a town, a port), a preset of its own: it replaces your main preset there. With a Zone preset you can also choose its color, which replaces the built-in mood. An area's choices win over its zone's."] = "Dale a la zona en la que estás, o solo al área dentro de ella (un pueblo, un puerto), un preajuste propio: sustituye a tu preajuste principal allí. Con un preajuste de Zona también puedes elegir su color, que sustituye al ambiente integrado. Lo elegido para un área manda sobre lo de su zona."
L[", |cffffd100%s|r preset"] = ", preajuste |cffffd100%s|r"
L["This zone: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "Esta zona: |cffffd100%s|r - %s%s, intensidad %d%%%s%s"
L[" (your choice)"] = " (elegido por ti)"
L[" (built in)"] = " (integrado)"
L[" (its own)"] = " (propia)"
L["This area: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "Esta área: |cffffd100%s|r - %s%s, intensidad %d%%%s%s"
L["Change:"] = "Cambiar:"
L["the zone"] = "la zona"
L["this area (%s)"] = "esta área (%s)"
L["this area (none here)"] = "esta área (ninguna aquí)"
L["Same as the zone"] = "Igual que la zona"
L["Main preset"] = "Preajuste principal"
L["Preset here"] = "Preajuste aquí"
L["A preset for the zone or area chosen above, used there instead of your main preset."] = "Un preajuste para la zona o el área elegida arriba, que se usa allí en lugar de tu preajuste principal."
L["Built-in mood"] = "Ambiente integrado"
L["No tint"] = "Sin tinte"
L["Pick a color..."] = "Elegir un color..."
L["Choose your own color for the zone or area chosen above (for the Zone presets)."] = "Elige tu propio color para la zona o el área elegida arriba (para los preajustes de Zona)."
L["Your zone tints"] = "Tus tintes de zona"
L["%s preset, "] = "preajuste %s, "
L[", %d%% strength"] = ", intensidad %d%%"
L["None yet."] = "Ninguno todavía."
L["...and %d more."] = "...y %d más."
L["At zone borders"] = "En los límites de zona"
L["Fade time"] = "Tiempo de transición"
L["With a Zone tint preset, crossing into a zone with a different mood fades the old mood out over this long, pauses, then fades the new one in over this long."] = "Con un preajuste de tinte de Zona, al entrar en una zona con otro ambiente, el ambiente anterior se desvanece durante este tiempo, hace una pausa y luego el nuevo aparece durante este tiempo."
L["Pause between tints when flying"] = "Pausa entre tintes al volar"
L["Untinted time between the two zones' moods while you're in the air, where you see the old zone's ground for longer (snow under an ember tint looks red)."] = "Tiempo sin tinte entre los ambientes de las dos zonas mientras estás en el aire, donde ves el suelo de la zona anterior durante más tiempo (la nieve bajo un tinte de brasas se ve roja)."
L["Pause between tints on the ground"] = "Pausa entre tintes en el suelo"
L["The same pause when you cross a border on foot or riding."] = "La misma pausa cuando cruzas un límite a pie o montado."
L["Vignette strength"] = "Intensidad de la viñeta"
L["Soft dark edges that draw the eye to the middle. Works with any tint."] = "Bordes oscuros suaves que llevan la vista al centro. Funciona con cualquier tinte."
L["Inns"] = "Posadas"
L["Light up inns"] = "Iluminar las posadas"
L["Indoors in an inn, the outdoor tint (a gloomy marsh, a moonlit night) partly lifts and a soft firelit glow fades in, colored by the zone: cooler in the snow, greener in a swamp. Blends over a few seconds as you go through the door."] = "Dentro de una posada, el tinte de exterior (un pantano lúgubre, una noche de luna) se aclara en parte y aparece un suave resplandor de hogar, con el color de la zona: más frío en la nieve, más verde en un pantano. Se mezcla durante unos segundos al cruzar la puerta."
L["Inn glow amount"] = "Brillo de posada"
L["How much light the glow adds at its brightest, low on the screen."] = "Cuánta luz añade el resplandor en su punto más brillante, en la parte baja de la pantalla."
L["Weather strength"] = "Intensidad del clima"
L["Rain grays and cools the scene, snow turns it pale blue and a sandstorm gives it a dusty orange haze, more strongly the heavier the weather. Works with any tint (None included), lifts under a roof and blends in as a storm builds. Needs a game version that reports the weather."] = "La lluvia vuelve la escena más gris y fría, la nieve la tiñe de azul pálido y una tormenta de arena le da una neblina anaranjada y polvorienta, con más fuerza cuanto más intenso es el tiempo. Funciona con cualquier tinte (Ninguno incluido), se retira bajo techo y se va mezclando a medida que crece una tormenta. Requiere una versión del juego que informe del clima."
L["Haze the screen edges in the camera modes"] = "Difuminar los bordes de la pantalla en los modos de cámara"
L["Camera haze"] = "Neblina de cámara"
L["Reduce view distance in rain"] = "Reducir la distancia de visión con lluvia"
L["In CineMode, as it rains, the view distance comes in from yours: the harder the rain, the closer. At 100% a downpour brings it all the way in, as far as the Graphics menu's lowest View distance; it never goes further out than yours. Yours is put back once the rain stops or you go indoors."] = "En modo cine, cuando llueve, la distancia de visión se acerca desde la tuya: cuanto más fuerte llueve, más cerca. Al 100% un aguacero la acerca del todo, hasta la distancia de visión más baja del menú de gráficos; nunca va más lejos que la tuya. La tuya vuelve en cuanto para la lluvia o entras bajo techo."
L["A soft haze around the edges of the screen in this camera mode, as if the camera had focused on you. 0% leaves it off. Moving the slider shows it for a moment. Needs \"Camera haze\" on the Visual Effects page, which also turns it up or down."] = "Una neblina suave en los bordes de la pantalla en este modo de cámara, como si la cámara se hubiera enfocado en ti. 0% la deja apagada. Al mover el control deslizante se muestra un momento. Necesita \"Neblina de cámara\" en la página de Efectos visuales, que también la sube o baja."
L["A soft haze around the edges of the screen in the camera modes, as if the camera had focused on you. Each camera mode's page sets its own strength: this turns them all up or down. /cine doftest shows it on demand."] = "Una neblina suave en los bordes de la pantalla en los modos de cámara, como si la cámara se hubiera enfocado en ti. La página de cada modo de cámara fija su propia intensidad: esto las sube o baja todas. /cine doftest la muestra cuando quieras."
L["A soft haze around the edges of the screen, as if the camera had focused on you. Each camera mode's page sets its own strength. /cine doftest shows it on demand."] = "Una neblina suave en los bordes de la pantalla, como si la cámara se hubiera enfocado en ti. La página de cada modo de cámara fija su propia intensidad. /cine doftest la muestra cuando quieras."
L["Sound during CineMode. Your own sound settings are saved first and put back afterwards, even after a crash. Pick which cameras play music as they start."] = "El sonido durante CineMode. Tus propios ajustes de sonido se guardan primero y se restauran después, incluso tras un cierre inesperado. Elige qué cámaras ponen música al empezar."
L["On: with your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone, bar the stops below. Off: CineMode leaves your music alone."] = "Activado: con la música del juego desactivada, cuando empieza una cámara (las marcadas en Música de la página Activadores de cámara) la activa y la hace aparecer poco a poco, a tu volumen de música; se desvanece cuando vuelve la interfaz y tu música se desactiva otra vez (también al salir del juego). Con la música del juego activada, no se toca, salvo las paradas de abajo. Desactivado: CineMode no toca tu música."
L["Music fade time"] = "Tiempo de transición de la música"
L["How long music takes to fade in or out with CineMode."] = "Cuánto tarda la música en aparecer o desvanecerse con CineMode."
L["Fatigue"] = "Cansancio"
L["Music fatigue"] = "Cansancio musical"
L["Once a camera has started music, no camera starts it again for this long, counted from when it started. The first camera after a login or /reload always can. Music coming back after a mute doesn't count. 0 turns this off."] = "Cuando una cámara ha puesto música, ninguna cámara vuelve a ponerla durante este tiempo, contado desde que empezó. La primera cámara tras conectarte o hacer /reload siempre puede. La música que vuelve tras silenciarse no cuenta. 0 lo desactiva."
L["Stop music"] = "Detener la música"
L["In combat"] = "En combate"
L["Music fades out over about a second when a fight starts, and a fresh track fades back in once the Calm Timer (on the CineMode page) has passed with no new fight. Works on your own game music too; your volume is put back afterwards."] = "La música se desvanece en algo más de un segundo cuando empieza un combate, y una pista nueva aparece cuando ha pasado el Temporizador de calma (en la página CineMode) sin un combate nuevo. Funciona también con tu propia música del juego; tu volumen se restaura después."
L["Leaving a camera mode"] = "Al salir de un modo de cámara"
L["Stop music leaving a camera mode"] = "Detener la música al salir de un modo de cámara"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Scenes page). Fades at the music fade time."] = "La música se desvanece cuando sales de los modos de cámara y sigues tu camino: al alejarte de la cámara acogedora, por ejemplo. Pasar de una cámara directamente a otra (de panorámica a acogedora) la mantiene sonando, igual que quedarte quieto. Una pista nueva aparece cuando empieza la siguiente cámara (quedarte quieto cuenta cuando empieza la cámara AFK, con la música de Ponerte ausente activada, página Escenas). Usa el tiempo de transición de la música."
L["In cities"] = "En ciudades"
L["In dungeons"] = "En mazmorras"
L["In raids"] = "En bandas"
L["In PvP"] = "En JcJ"
L["Music fades out here (your own game music too) and back in when you leave."] = "La música se desvanece aquí (también tu propia música del juego) y vuelve cuando te vas."
L["Tar enemy"] = "Obj. enemigo"
L["Tar friendly"] = "Obj. amistoso"
L["More settings on the %s page. They can keep it up beyond what's ticked here (hovering, tracking, new auras, cooldowns recharging and the like)."] = "Más ajustes en la página %s. Pueden mantenerlo visible más allá de lo marcado aquí (al pasar el ratón, rastreo, auras nuevas, reutilizaciones en curso y similares)."
L["Show it whenever its frame shows. This overrides its Hover groups: untick it to hide it in CineMode except when hovered or brought up by the other columns."] = "Se muestra siempre que se muestre su marco. Esto tiene prioridad sobre sus grupos de Pasar el ratón: desmárcalo para ocultarlo en CineMode salvo al pasar el ratón o cuando lo muestren las otras columnas."
L["Show it all through CineMode, instead of hiding it. (The other columns then have nothing to add.)"] = "Se muestra durante todo CineMode, en lugar de ocultarse. (Las otras columnas ya no tienen nada que añadir.)"
L["Standard Frames"] = "Marcos estándar"
L["Everything here is hidden in CineMode unless ticked. Tick a column to show that frame: Always shows it the whole time, the next three only while you fight or have something targeted, and the places the whole time while you're there (Grouped: in a party or raid). Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "Todo lo de aquí se oculta en CineMode salvo que esté marcado. Marca una columna para mostrar ese marco: Siempre lo muestra todo el tiempo, las tres siguientes solo mientras combates o tienes algo seleccionado, y los lugares todo el tiempo mientras estás en ellos (En grupo: en un grupo o banda). Los marcos aparecen y se desvanecen con los tiempos de la página CineMode. Los marcos de otros accesorios están en la página Marcos de addons."
L["Enable Page"] = "Activar página"
L["On. Right-click to turn this page off."] = "Activada. Haz clic derecho para desactivar esta página."
L["Off. Right-click to turn this page on."] = "Desactivada. Haz clic derecho para activar esta página."
L["Off with the General page's switch."] = "Desactivada con el interruptor de la página General."
L["%s is off"] = "%s está desactivada"
L["Turn it on to see and change its settings."] = "Actívala para ver y cambiar sus ajustes."
L["Turn on %s"] = "Activar %s"
L["Enable Style"] = "Activar Estilo"
L["Enable Cameras"] = "Activar cámaras"
L["Enable Visual Effects"] = "Activar efectos visuales"
L["On: everything below works as ticked. Off: none of it does, and each keeps its tick for when you turn this back on."] = "Activado: todo lo de abajo funciona como esté marcado. Desactivado: nada de ello funciona, y cada opción conserva su marca para cuando lo vuelvas a activar."
L["On: the unit frames show the parts the grids below say. Off: CineMode leaves them alone, every part showing as the game has it."] = "Activado: los marcos de unidad muestran las partes que dicen las cuadrículas de abajo. Desactivado: CineMode no los toca y todas las partes se ven como las tiene el juego."
L["On: CineMode fades the frames on this page as their rows say. Off: it leaves them all alone, the minimap, quest tracker, buffs and Cooldown Manager included (their pages' switches only count while this is on)."] = "Activado: CineMode desvanece los marcos de esta página según sus filas. Desactivado: los deja todos en paz, incluidos el minimapa, el seguimiento de misiones, los beneficios y el Gestor de reutilización (los interruptores de sus páginas solo cuentan mientras esto está activado)."
L["In combat rows stay for the Calm Timer"] = "Las filas En combate siguen durante el Temporizador de calma"
L["Frames ticked In combat (here and on the Addon Frames page) stay up after a fight until the Calm Timer (CineMode page) has run out, then fade. Off: they fade as soon as the fight ends."] = "Los marcos marcados En combate (aquí y en la página Marcos de addons) siguen visibles después de un combate hasta que se agota el Temporizador de calma (página CineMode), y luego se desvanecen. Desactivado: se desvanecen en cuanto acaba el combate."
L["Cast fade into combat"] = "Aparición al lanzar hacia el combate"
L["Out of combat, casting a spell at an enemy brings up the frames ticked In combat, as if the fight had started: they fade in over the cast and are fully up as it lands. Instant spells bring them up at the Combat fade in time."] = "Fuera de combate, lanzar un hechizo a un enemigo muestra los marcos marcados En combate, como si el combate hubiera empezado: aparecen poco a poco durante el lanzamiento y están del todo visibles cuando impacta. Los hechizos instantáneos los muestran con el Tiempo de aparición en combate."
L["Unit frames"] = "Marcos de unidad"
L["Interface"] = "Interfaz"
L["Party frames (not raid-style)"] = "Marcos de grupo (no estilo banda)"
L["Party frames (raid-style)"] = "Marcos de grupo (estilo banda)"
L["Same as raid frames"] = "Igual que los marcos de banda"
L["Ticked: party frames shown raid-style (the game's Use Raid-Style Party Frames, in Edit Mode) fade as the Raid tab's rows say. Untick it to give them rows of their own."] = "Marcado: los marcos de grupo con estilo de banda (la opción del juego Usar marcos de grupo con estilo de banda, en el Modo edición) se desvanecen según las filas de la pestaña Banda. Desmárcalo para darles filas propias."
L["Battlegrounds"] = "Campos de batalla"
L["Arenas"] = "Arenas"
L["Other"] = "Otros"
L["Fishing"] = "Pesca"
L["Casting and catching, with the mouse or a gamepad, CineMode or not."] = "Lanzar y capturar, con el ratón o con un mando, con CineMode o sin él."
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Scenes page.)"] = "Activado: el clic derecho (o un botón del mando) vuelve a lanzar, y la barra de lanzamiento de Pesca se oculta, según esta página. Desactivado: la pesca queda en manos del juego. (La cámara de pesca está en la página Escenas.)"
L["Casting"] = "Lanzamiento"
L["Hide the Fishing cast bar"] = "Ocultar la barra de lanzamiento de Pesca"
L["Your cast bar stays hidden while it shows Fishing. Every other spell shows it as usual."] = "Tu barra de lanzamiento se queda oculta mientras muestra Pesca. Con cualquier otro hechizo se muestra como siempre."
L["Right-click to cast again"] = "Clic derecho para volver a lanzar"
L["Also the first cast, with a pole equipped"] = "También el primer lanzamiento, con una caña equipada"
L["With a fishing pole in your main hand, standing still, right-clicking in the world casts Fishing, so you don't have to start the first cast yourself. Not while your mouse is on a player, NPC or object (mailbox, corpse...): right-click works on them as usual. Swap the pole out to have right-click back everywhere."] = "Con una caña de pescar en la mano principal y estando quieto, hacer clic derecho en el mundo lanza Pesca, así que no tienes que empezar tú el primer lanzamiento. No mientras el ratón está sobre un jugador, PNJ u objeto (buzón, cadáver...): el clic derecho funciona con ellos como siempre. Quítate la caña para recuperar el clic derecho en todas partes."
L["Wait after a cast ends"] = "Espera tras acabar un lanzamiento"
L["How long after a cast ends (a catch looted, or the bobber gone) before right-click casts again, so the click that loots the fish doesn't cast straight away."] = "Cuánto tiempo pasa tras acabar un lanzamiento (una captura despojada, o el corcho desaparecido) antes de que el clic derecho vuelva a lanzar, para que el clic que despoja el pez no lance al momento."
L["Pause after a missed cast"] = "Pausa tras un lanzamiento fallido"
L["When a cast doesn't land in fishable water (say, a pole left equipped away from water), right-click goes back to normal for this long before it casts again. Moving and then standing still for 1 sec ends it early: you're likely at a new spot to fish from. Off doesn't pause. (\"Skill not high enough\" always pauses it for 30 sec, moving or not.)"] = "Cuando un lanzamiento no cae en agua de pesca (por ejemplo, con una caña equipada lejos del agua), el clic derecho vuelve a la normalidad durante este tiempo antes de volver a lanzar. Moverte y luego quedarte quieto 1 s la termina antes: probablemente estás en un sitio nuevo para pescar. Desactivado no hace pausa. («Habilidad insuficiente» siempre la pausa 30 s, te muevas o no.)"
L["Gamepad: a button casts too"] = "Mando: un botón también lanza"
L["In gamepad mode, the button below casts Fishing whenever right-click would: in the fish camera with no bobber out, and (if ticked above) with a pole equipped, standing still. The rest of the time it does what it usually does. Each cast still comes from your own press."] = "En el modo mando, el botón de abajo lanza Pesca siempre que lo haría el clic derecho: en la cámara de pesca sin corcho fuera, y (si está marcado arriba) con una caña equipada, estando quieto. El resto del tiempo hace lo de siempre. Cada lanzamiento sigue saliendo de tu propia pulsación."
L["Left face button (Xbox X)"] = "Botón frontal izquierdo (X en Xbox)"
L["Top face button (Xbox Y)"] = "Botón frontal superior (Y en Xbox)"
L["Bottom face button (Xbox A)"] = "Botón frontal inferior (A en Xbox)"
L["Right face button (Xbox B)"] = "Botón frontal derecho (B en Xbox)"
L["The gamepad button that casts Fishing."] = "El botón del mando que lanza Pesca."
L["Gamepad"] = "Mando"
L["The frames gamepad mode adds (Options, Controls, Gamepad): its action bars, the button hints and the reticle (the dot you aim with). As on the Game Frames page, each is hidden in CineMode unless ticked: Always shows it the whole time, the next three only while you fight or have something targeted, and the places while you're there. Rows also on the Game Frames page (the experience bars) follow this page in gamepad mode, and that one otherwise."] = "Los marcos que añade el modo mando (Opciones, Controles, Mando): sus barras de acción, las ayudas de botones y la retícula (el punto con el que apuntas). Como en la página Marcos del juego, cada uno se oculta en CineMode salvo que esté marcado: Siempre lo muestra todo el tiempo, las tres siguientes solo mientras combates o tienes algo seleccionado, y los lugares mientras estás en ellos. Las filas que también están en la página Marcos del juego (las barras de experiencia) siguen esta página en el modo mando, y aquella en los demás casos."
L["On: CineMode fades the gamepad's bars, button hints and reticle as this page says. Off: it leaves them alone."] = "Activado: CineMode desvanece las barras, las ayudas de botones y la retícula del mando según esta página. Desactivado: los deja en paz."
L["Show the interact prompt (X)"] = "Mostrar el aviso de interacción (X)"
L["The button prompt over things you can use or talk to (your bobber, an NPC) stays up in CineMode while the nameplates fade, so you can see what the gamepad can reach: a bobber showing it can be caught. Unticked, it fades with them."] = "El aviso de botón sobre lo que puedes usar o con quien puedes hablar (tu corcho, un PNJ) sigue visible en CineMode mientras las placas de nombre se desvanecen, para que veas a qué llega el mando: un corcho que lo muestra se puede recoger. Desmarcado, se desvanece con ellas."
L["Show the action bars when you press a button"] = "Mostrar las barras de acción al pulsar un botón"
L["Gamepad mode's mouseover: pressing any gamepad button brings the action bars up, and they fade out again your \"stays after mouseover\" time later (Hover groups page). Each press starts that time again. Choose the buttons in the list below. Presses that make you jump don't count (whichever button jumps), nor presses while you fish (the fish camera on, a cast going, or looting)."] = "El «pasar el ratón» del modo mando: pulsar cualquier botón del mando muestra las barras de acción, y vuelven a desvanecerse pasado tu tiempo de «Sigue tras pasar el ratón» (página Grupos al pasar el ratón). Cada pulsación reinicia ese tiempo. Elige los botones en la lista de abajo. Las pulsaciones que te hacen saltar no cuentan (sea cual sea el botón de saltar), ni las pulsaciones mientras pescas (la cámara de pesca activa, un lanzamiento en curso, o despojando)."
L["Buttons that show them"] = "Botones que las muestran"
L["Click to show or hide the list of buttons: untick one and pressing it doesn't bring the action bars up."] = "Haz clic para mostrar u ocultar la lista de botones: desmarca uno y pulsarlo no muestra las barras de acción."
L["Action bar fading"] = "Desvanecimiento de las barras de acción"
L["Stay after a press"] = "Siguen tras una pulsación"
L["How long the action bars stay after your last button press, counting their fade out."] = "Cuánto tiempo siguen las barras de acción tras tu última pulsación, contando su desvanecimiento."
L["How long the gamepad action bars take to fade in: for button presses, fights and targets alike. The rest of the UI uses the fade times on the CineMode page."] = "Cuánto tardan las barras de acción del mando en aparecer: para pulsaciones, combates y objetivos por igual. El resto de la interfaz usa los tiempos de la página CineMode."
L["How long the gamepad action bars take to fade out."] = "Cuánto tardan las barras de acción del mando en desvanecerse."
L["Nameplates"] = "Placas de nombre"
L["Nameplate & Names"] = "Placas de nombre y nombres"
L["Friendly nameplates"] = "Placas de nombre amistosas"
L["Enemy nameplates"] = "Placas de nombre enemigas"
L["Which nameplates and names stay up in CineMode: in groups, in fights and in each kind of place."] = "Qué placas de nombre y nombres siguen visibles en CineMode: en grupo, en combate y en cada tipo de lugar."
L["Duel Vision"] = "Visión de duelo"
L["In CineMode, the nameplates of two players dueling near you show, so you can watch their health. " ..
	"Only in the open world, out of fights. Turns on friendly player nameplates while it watches, " ..
	"kept invisible and click-through bar the duelists'. Each duel has its own color, and the winner " ..
	"and loser show when it ends. Needs the Nameplates page enabled."] =
	"En CineMode se muestran las placas de nombre de dos jugadores que se baten en duelo cerca de ti, para ver su salud. " ..
	"Solo en el mundo abierto y fuera de combate. Mientras vigila, activa las placas de jugadores amistosos, " ..
	"invisibles y sin bloquear clics salvo las de los duelistas. Cada duelo tiene su propio color, y al terminar " ..
	"se muestra quién ganó y quién perdió. Necesita la página Placas de nombre activada."
L["Crowd control"] = "Control de masas"
L["A feared, stunned, polymorphed, rooted or silenced duelist gets an icon of the spell beside their " ..
	"nameplate, with the time left."] =
	"Un duelista asustado, aturdido, polimorfado, enraizado o silenciado muestra un icono del hechizo junto a su " ..
	"placa de nombre, con el tiempo restante."
L["Won"] = "Ganó"
L["Lost"] = "Perdió"
L["Fled"] = "Huyó"
L["Nameplate distance"] = "Distancia de las placas de nombre"
L["How far away nameplates show, in yards. " ..
	"The game won't go past its own limit. Reset page puts the game's default back."] =
	"Hasta qué distancia se ven las placas de nombre, en metros. " ..
	"El juego no pasa de su propio límite. Restablecer página vuelve a poner el valor por defecto del juego."
L["Max zoom distance"] = "Distancia máxima del zoom"
L["How far out you can zoom the camera, as times the " ..
	"game's base distance. The game won't go past its own limit. Idle zoom's \"past your max\" still " ..
	"raises it to 2.6 while it zooms, if it's lower."] =
	"Hasta dónde puedes alejar la cámara, en veces la distancia base del juego. El juego no pasa de su " ..
	"propio límite. El \"más allá de tu máximo\" del zoom en reposo aún lo sube a 2.6 mientras hace zoom, " ..
	"si es menor."
L["The game's menu doesn't change it. Its default is %s."] = "El menú del juego no lo cambia. Su valor por defecto es %s."
L["On: CineMode fades nameplates and names as this page says. Off: it leaves them alone, and the game's own options decide, in CineMode and out."] = "Activado: CineMode desvanece las placas de nombre y los nombres según esta página. Desactivado: los deja en paz y deciden las opciones del propio juego, con CineMode y sin él."
L["Show in fights, and for the Calm Timer after."] = "Se muestran en combate, y durante el Temporizador de calma posterior."
L["Show in fights while you're PvP flagged, and for the Calm Timer after."] = "Se muestran en combate mientras tienes el JcJ activado, y durante el Temporizador de calma posterior."
L["Always show while you're in a party or raid."] = "Se muestran siempre mientras estás en un grupo o banda."
L["Blizzard's Always Show Nameplates is off, so nameplates only show in combat."] = "La opción de Blizzard Mostrar siempre placas de nombre está desactivada, así que las placas solo se muestran en combate."
L["Target Nameplate"] = "Placa de nombre del objetivo"
L["Target circle"] = "Círculo del objetivo"
L["The selection circle on the ground under your target. Hidden, your own setting is put back when the UI returns."] = "El círculo de selección en el suelo bajo tu objetivo. Al ocultarlo, tu ajuste se restablece cuando vuelve la interfaz."
L["Plate parts"] = "Partes de la placa"
L["Cinematic plate parts"] = "Partes de la placa de Cinematic"
L["Dungeons & raids"] = "Mazmorras y bandas"
L["Cinematic parts"] = "Partes de Cinematic"
L["Raid-style"] = "Estilo banda"
L["Essential"] = "Esenciales"
L["Utility"] = "Utilidad"
L["Other buffs"] = "Otros beneficios"
L[" In CineMode, on the nameplates that are up."] = " En CineMode, en las placas de nombre que están visibles."
L[" The health bar."] = " La barra de salud."
L["Name"] = "Nombre"
L[" The name on the plate (the Names grid below is for names without a plate)."] = " El nombre en la placa (la tabla Nombres de abajo es para los nombres sin placa)."
L[" The cast bar."] = " La barra de lanzamiento."
L[" The buffs shown on the plate."] = " Los beneficios que se muestran en la placa."
L[" The debuffs (and crowd control) shown on the plate."] = " Los perjuicios (y el control de masas) que se muestran en la placa."
L["Raid marker"] = "Marca de banda"
L["Raid Markers"] = "Marcas de banda"
L["Friendly"] = "Amistosos"
L["Enemy"] = "Enemigos"
L["The game draws the raid marker over your own head itself, not on a nameplate, and doesn't let addons hide it."] = "El juego dibuja la marca de banda sobre tu propia cabeza por sí mismo, no en una placa de nombre, y no deja que los addons la oculten."
L[" Ticked, their raid markers (skull, moon...) stay over them in CineMode as the rest of their nameplates fades, so your group can still see what's marked. Unticked, they fade with the plates."] = " Marcado, sus marcas de banda (calavera, luna...) se quedan sobre ellos en CineMode mientras el resto de sus placas de nombre se desvanece, para que tu grupo siga viendo qué está marcado. Desmarcado, se desvanecen con las placas."
L[" Friendly units."] = " Unidades amistosas."
L[" Unticked, friendly players get invisible nameplates you click through, or the game would draw their markers over their heads itself. Not in dungeons and raids, where Friendly plates in dungeons and raids decides their plates."] = " Desmarcado, los jugadores amistosos reciben placas de nombre invisibles que no se pueden pulsar; si no, el juego dibujaría sus marcas sobre sus cabezas por sí mismo. No en mazmorras ni bandas, donde Placas amistosas en mazmorras y bandas decide sus placas."
L[" Enemy and neutral units."] = " Unidades enemigas y neutrales."
L[" The raid target marker (skull, star...)."] = " La marca de objetivo de banda (calavera, estrella...)."
L["Elite/rare icon"] = "Icono de élite/raro"
L[" The elite, rare or boss icon."] = " El icono de élite, raro o jefe."
L["Level"] = "Nivel"
L[" The level."] = " El nivel."
L["Threat glow"] = "Brillo de amenaza"
L[" The glow while a mob has you (or is about to) as its target."] = " El brillo mientras un enemigo te tiene (o está a punto de tenerte) como objetivo."
L[" The border round your target's or mouseover's plate."] = " El borde alrededor de la placa de tu objetivo o de la que tienes bajo el ratón."
L["Quest/widget icons"] = "Iconos de misión/widgets"
L[" Quest objective icons and other widgets over the plate."] = " Los iconos de objetivos de misión y otros widgets sobre la placa."
L["Class icon (friendly)"] = "Icono de clase (aliados)"
L["Class icon (enemy)"] = "Icono de clase (enemigos)"
L[" A class icon beside friendly players' health bars."] = " Un icono de clase junto a la barra de salud de los jugadores aliados."
L[" A class icon beside enemy players' health bars."] = " Un icono de clase junto a la barra de salud de los jugadores enemigos."
L["Role icon (tank)"] = "Icono de rol (tanque)"
L["Role icon (healer)"] = "Icono de rol (sanador)"
L["Role icon (damage)"] = "Icono de rol (daño)"
L[" A role icon beside your group's tanks' health bars."] = " Un icono de rol junto a la barra de salud de los tanques de tu grupo."
L[" A role icon beside your group's healers' health bars."] = " Un icono de rol junto a la barra de salud de los sanadores de tu grupo."
L[" A role icon beside your group's damage dealers' health bars."] = " Un icono de rol junto a la barra de salud de quienes hacen daño en tu grupo."
L["Target Arrow"] = "Flecha de objetivo"
L["Style"] = "Estilo"
L["Target Indicator"] = "Indicador de objetivo"
L["How your target, focus and the unit under the mouse stand out on the nameplates, for when no target frame shows them: a mark on each one's plate, a row for each in the grid, and its name, health bar or border in its mark's color (the row's Also color). When they show is the Target Indicator row's, on the Nameplates page's Cinematic plate parts grid. Changes show at once, here and on the plates."] = "Cómo destacan tu objetivo, tu foco y la unidad bajo el ratón en las placas de nombre, para cuando ningún marco de objetivo los muestra: una marca en la placa de cada uno, una fila para cada uno en la cuadrícula, y su nombre, barra de salud o borde en el color de su marca (la columna Colorear también de la fila). Cuándo aparecen lo decide la fila Indicador de objetivo, en la cuadrícula Partes de la placa de Cinematic de la página Placas de nombre. Los cambios se ven al instante, aquí y en las placas."
L["Also color"] = "Colorear también"
L["Bar"] = "Barra"
L["The unit's name in its mark's color, on its plate or shown alone."] = "El nombre de la unidad en el color de su marca, en su placa o mostrado solo."
L["The unit's health bar in its mark's color."] = "La barra de salud de la unidad en el color de su marca."
L["The unit's own parts in its mark's color: its name and health bar (and on your target, the game's border round it)."] = "Partes de la propia unidad en el color de su marca: su nombre y su barra de salud (y en tu objetivo, el borde que el juego pone a su alrededor)."
L["Your target."] = "Tu objetivo."
L["Aggro on you"] = "Amenaza sobre ti"
L["Any enemy attacking you (you have its aggro). Above the Target row, or that one wins on your target. A cell set to Your target's takes the Target row's; change it to set this one apart."] = "Cualquier enemigo que te ataca (tienes su amenaza). Por encima de la fila Objetivo, o esa gana en tu objetivo. Una celda en De tu objetivo toma la de la fila Objetivo; cámbiala para diferenciarla."
L["Aggro on not you"] = "Amenaza sobre otro"
L["Any enemy in a fight attacking someone friendly other than you: a group member, a pet or another player. For a tank, the ones to pick up."] = "Cualquier enemigo en combate que ataca a alguien amistoso que no eres tú: un miembro del grupo, una mascota u otro jugador. Para un tanque, los que hay que recoger."
L["Aggro on non-tank"] = "Amenaza sobre no tanque"
L["Any enemy attacking a player who isn't a tank (you too, unless you're one): for a healer, who's in trouble; for a tank, the ones to taunt. A pet tanking doesn't count."] = "Cualquier enemigo que ataca a un jugador que no es tanque (también tú, salvo que lo seas): para un sanador, quién está en apuros; para un tanque, los que hay que provocar. Una mascota tanqueando no cuenta."
L["Aggro on a healer"] = "Amenaza sobre sanador"
L["Any enemy attacking a healer (you too, if you're one): for a healer, who's after you or the other healers; for a tank, the ones to pull off them."] = "Cualquier enemigo que ataque a un sanador (a ti también, si lo eres): para un sanador, quién va a por ti o los otros sanadores; para un tanque, los que hay que quitarles de encima."
L["A plate takes its whole look (mark, colors, opacity) from the first row that fits it, top to bottom; the rows below aren't looked at. Click a row to open its settings: its mark, the plate's colors and opacity, and When it fits. The chips beside its name show what's set apart from the usual. Move a row with its arrows, copy it with its two squares, take it off with its x. Add row puts a new one at the end; its Row line says what it's for: a Kind, for Aggro and Units which of them, Who for just its enemies, neutral units or friends, and Distance for just those within or past 11, 28 or 40 yards (Any unit past 40 yards fades far plates). The same kind again is another row of it (Target (2)), say with a different When for raids. Put a row for just some units above its kind's own row, so it comes first for them. Default, always last, is for plates no row fits: the game's look unless you change it."] = "Una placa toma todo su aspecto (marca, colores, opacidad) de la primera fila que encaja con ella, de arriba abajo; las filas de debajo no se miran. Haz clic en una fila para abrir sus ajustes: su marca, los colores y la opacidad de la placa, y Cuándo encaja. Las etiquetas junto a su nombre muestran lo que se aparta de lo habitual. Mueve una fila con sus flechas, cópiala con sus dos cuadrados y quítala con su x. Añadir fila pone una nueva al final; su línea Fila dice para qué es: un Tipo, para Amenaza y Unidades cuál de ellos, Quién para solo sus enemigos, neutrales o amistosos, y Distancia para solo los que están a menos o a más de 11, 28 o 40 metros (Cualquier unidad a más de 40 metros atenúa las placas lejanas). El mismo tipo otra vez es otra fila (Objetivo (2)), por ejemplo con otro Cuándo para bandas. Pon una fila para solo algunas unidades encima de la fila propia de su tipo, para que vaya primero para ellas. Predeterminado, siempre al final, es para las placas que ninguna fila encaja: el aspecto del juego a menos que lo cambies."
