L["The bubble's color, for Custom."] = "El color del bocadillo, para Personalizado."
L["How see-through the bubble is."] = "Lo translúcido que es el bocadillo."
L["Edge:"] = "Borde:"
L["A thin line around the bubble."] = "Una línea fina alrededor del bocadillo."
