-- ProfilerPage.lua: the Profiler page (Community)
L["Profiler"] = "Perfilador"
L["How much of your computer's time Cinematic takes. The graph is the game's own figure for this addon: its share of each frame's time, sampled every second (the last five minutes, kept over a reload), each bar colored by what was going on. A recording times the addon's busy parts: it starts when you close the settings, and its results show here. If Cinematic seems slow for you, record a while of your usual play (a fight too), then Copy report and send it to us: it helps us find what to speed up."] = "Cuánto tiempo de tu ordenador usa Cinematic. La gráfica es la cifra del propio juego para este addon: su parte del tiempo de cada fotograma, medida cada segundo (los últimos cinco minutos, se conservan al recargar), cada barra coloreada según lo que pasaba. Una grabación cronometra las partes más ocupadas del addon: empieza al cerrar los ajustes y sus resultados se muestran aquí. Si Cinematic te parece lento, graba un rato de tu juego habitual (con algún combate), luego Copiar informe y envíanoslo: nos ayuda a saber qué acelerar."
L["On: the graph samples the game's figure every second and keeps it over a reload, and you can record. Off (to start with): nothing is sampled or saved, and it costs nothing."] = "Activado: la gráfica mide la cifra del juego cada segundo y la conserva al recargar, y puedes grabar. Desactivado (al principio): no se mide ni se guarda nada, y no cuesta nada."
L["The game's figure, the last five minutes"] = "La cifra del juego, los últimos cinco minutos"
L["normal UI"] = "interfaz normal"
L["CineMode"] = "CineMode"
L["in a fight"] = "en combate"
L["settings open"] = "ajustes abiertos"
L["average"] = "media"
L["The game's profiler isn't on this client: use a recording below."] = "El perfilador del juego no está en este cliente: usa una grabación abajo."
L["No samples yet (one a second)."] = "Aún no hay muestras (una por segundo)."
L["Off: right-click the Profiler icon to sample."] = "Desactivado: haz clic derecho en el icono del Perfilador para medir."
L["%s |cffffd100%.1f%%|r (%.3f ms a frame, %d s)"] = "%s |cffffd100%.1f%%|r (%.3f ms por fotograma, %d s)"
L["%s, %d s ago"] = "%s, hace %d s"
L["Cinematic %.1f%% of the frame: %.3f ms of %.2f ms (%.0f fps)"] = "Cinematic %.1f%% del fotograma: %.3f ms de %.2f ms (%.0f fps)"
L["All addons %.1f%% (%.3f ms)"] = "Todos los addons %.1f%% (%.3f ms)"
L["%s, camera %s"] = "%s, cámara %s"
L["none"] = "ninguna"
L["Recording (the addon's own timers)"] = "Grabación (los cronómetros del propio addon)"
L["Starts when you close the settings: %d seconds, detailed."] = "Empieza al cerrar los ajustes: %d segundos, detallada."
L["Starts when you close the settings: %d seconds."] = "Empieza al cerrar los ajustes: %d segundos."
L["Copy report"] = "Copiar informe"
L["Profiler: press Ctrl+C to copy"] = "Perfilador: pulsa Ctrl+C para copiar"
L["%.4f ms a frame, %.2f calls a frame"] = "%.4f ms por fotograma, %.2f llamadas por fotograma"
L["average %.4f ms a call, worst %.2f ms"] = "media %.4f ms por llamada, peor %.2f ms"
L["%.1f KB of garbage a second"] = "%.1f KB de basura por segundo"
